starter.css:
.barra {
  padding: 12px;
}

.menu-botao {
  display: none;
}

.links {
  display: flex;
  gap: 12px;
}

solution.css:
.barra {
  padding: 12px;
}

.menu-botao {
  display: inline-block;
}

.links {
  display: none;
}

@media (min-width: 900px) {
  .menu-botao {
    display: none;
  }

  .links {
    display: flex;
    gap: 12px;
  }
}
